// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListBookingDiscrepancies Tenant-wide report of every completed booking's under-scanned line items and damaged/lost stock -- derived on demand, not persisted.
	// (GET /procurement/bookings/discrepancies)
	ListBookingDiscrepancies(c *gin.Context)
	// GetBooking Scanner app -- get a booking with its PO line items and scan history, for the progress view
	// (GET /procurement/bookings/{id})
	GetBooking(c *gin.Context, id Id)
	// CompleteBooking Scanner app -- finish a booking; returns a missing-items report if any PO line wasn't fully scanned. completed_by is taken from the caller's own JWT claims, not the request body.
	// (POST /procurement/bookings/{id}/complete)
	CompleteBooking(c *gin.Context, id Id)
	// PauseBooking Scanner app -- pause an in-progress booking
	// (POST /procurement/bookings/{id}/pause)
	PauseBooking(c *gin.Context, id Id)
	// ResolveBookingScanCode Scanner app -- resolve a scanned barcode/box-alias/SKU code (or this PO's own line item raw SKU) to a SKU, without booking anything yet. Lets the app show a confirm screen (quantity, batch) before staging a BookingScan via POST .../scan.
	// (POST /procurement/bookings/{id}/resolve-scan)
	ResolveBookingScanCode(c *gin.Context, id Id)
	// ScanBookingItem Scanner app -- resolve a scanned barcode/box-alias to a SKU and book received stock for it
	// (POST /procurement/bookings/{id}/scan)
	ScanBookingItem(c *gin.Context, id Id)
	// DeleteBookingScan Scanner app -- remove a staged scan before it's been replayed to real inventory (correct a mis-scan, e.g. a damaged/lost entry logged in error). Only legal while the booking is still in_progress.
	// (DELETE /procurement/bookings/{id}/scans/{scanId})
	DeleteBookingScan(c *gin.Context, id Id, scanId ScanId)
	// GetDocumentParsingJob Poll a document parsing job's status -- terminal states carry error_message on failure
	// (GET /procurement/document-parsing-jobs/{id})
	GetDocumentParsingJob(c *gin.Context, id Id)
	// DeletePurchaseOrderDocument Delete an uploaded purchase order document (and its stored file). Does not affect any line items already created from it.
	// (DELETE /procurement/purchase-order-documents/{id})
	DeletePurchaseOrderDocument(c *gin.Context, id Id)
	// RetryDocumentParsingJob Re-enqueue AI parsing for a document whose most recent parsing job failed -- the document's already-stored file is re-parsed, no re-upload needed. Returns the new job to poll (same shape as the initial attach), same "pending -> running -> completed/failed" lifecycle cmd/scheduler drives.
	// (POST /procurement/purchase-order-documents/{id}/retry)
	RetryDocumentParsingJob(c *gin.Context, id Id)
	// RemovePurchaseOrderLineItem Remove a purchase order line item
	// (DELETE /procurement/purchase-order-line-items/{id})
	RemovePurchaseOrderLineItem(c *gin.Context, id Id)
	// UpdatePurchaseOrderLineItem Update a purchase order line item
	// (PATCH /procurement/purchase-order-line-items/{id})
	UpdatePurchaseOrderLineItem(c *gin.Context, id Id)
	// CreateProductAndLinkLineItem Review UI action -- create a new product/SKU from an unmatched line item and link it
	// (POST /procurement/purchase-order-line-items/{id}/create-product-and-link)
	CreateProductAndLinkLineItem(c *gin.Context, id Id)
	// GetLandedUnitCost Compute a product line item's landed unit cost (own cost plus a proportional share of the order's shipping/fee lines)
	// (GET /procurement/purchase-order-line-items/{id}/landed-cost)
	GetLandedUnitCost(c *gin.Context, id Id)
	// LinkLineItemToSku Review UI action -- link an unmatched line item to an existing SKU, learning the correction for next time
	// (POST /procurement/purchase-order-line-items/{id}/link)
	LinkLineItemToSku(c *gin.Context, id Id)
	// ListPurchaseOrders List purchase orders for the current tenant
	// (GET /procurement/purchase-orders)
	ListPurchaseOrders(c *gin.Context)
	// CreatePurchaseOrder Create a purchase order (always starts as draft)
	// (POST /procurement/purchase-orders)
	CreatePurchaseOrder(c *gin.Context)
	// CreatePurchaseOrderFromDocument Upload a PDF/CSV/XLSX document to create a new draft purchase order from it. supplier_id is optional -- omit it to send the PO straight to needs_review for a human to link or create a supplier.
	// (POST /procurement/purchase-orders/documents)
	CreatePurchaseOrderFromDocument(c *gin.Context)
	// DeletePurchaseOrder Delete a purchase order (cascades its line items)
	// (DELETE /procurement/purchase-orders/{id})
	DeletePurchaseOrder(c *gin.Context, id Id)
	// GetPurchaseOrder Get a purchase order with its line items
	// (GET /procurement/purchase-orders/{id})
	GetPurchaseOrder(c *gin.Context, id Id)
	// UpdatePurchaseOrder Update a purchase order's header fields (incl. status)
	// (PATCH /procurement/purchase-orders/{id})
	UpdatePurchaseOrder(c *gin.Context, id Id)
	// StartOrResumeBooking Scanner app -- start a new booking session for this PO, or resume its existing in_progress/paused one. warehouse_id is required the first time (when the PO has none yet) and ignored afterward.
	// (POST /procurement/purchase-orders/{id}/booking)
	StartOrResumeBooking(c *gin.Context, id Id)
	// CreateSupplierAndAssignToPurchaseOrder Review UI action -- create a new supplier from a PO that was uploaded without one, and assign it
	// (POST /procurement/purchase-orders/{id}/create-supplier-and-assign)
	CreateSupplierAndAssignToPurchaseOrder(c *gin.Context, id Id)
	// AttachDocumentToPurchaseOrder Upload a PDF/CSV/XLSX document and attach it to an existing purchase order for parsing
	// (POST /procurement/purchase-orders/{id}/documents)
	AttachDocumentToPurchaseOrder(c *gin.Context, id Id)
	// UploadInvoice Upload a supplier invoice (PDF/CSV/XLSX) against an existing purchase order for parsing + reconciliation
	// (POST /procurement/purchase-orders/{id}/invoices)
	UploadInvoice(c *gin.Context, id Id)
	// AddPurchaseOrderLineItem Add a line item to a purchase order
	// (POST /procurement/purchase-orders/{id}/line-items)
	AddPurchaseOrderLineItem(c *gin.Context, id Id)
	// ListReceivingRecords List receiving records (invoice uploads) for a purchase order
	// (GET /procurement/purchase-orders/{id}/receiving-records)
	ListReceivingRecords(c *gin.Context, id Id)
	// LinkReceivingDiscrepancies Review UI action -- pair an unexpected_item with a missing_item a human recognizes as the same product, acknowledging both
	// (POST /procurement/receiving-discrepancies/link)
	LinkReceivingDiscrepancies(c *gin.Context)
	// AcknowledgeReceivingDiscrepancy Review UI action -- mark a single discrepancy reviewed ("mark as valid"); never affects stock booking
	// (POST /procurement/receiving-discrepancies/{id}/acknowledge)
	AcknowledgeReceivingDiscrepancy(c *gin.Context, id Id)
	// GetReceivingParsingJob Poll a receiving (invoice) parsing job's status -- terminal states carry error_message on failure
	// (GET /procurement/receiving-parsing-jobs/{id})
	GetReceivingParsingJob(c *gin.Context, id Id)
	// GetReceivingRecord Get a receiving record with its discrepancies, for the review UI
	// (GET /procurement/receiving-records/{id})
	GetReceivingRecord(c *gin.Context, id Id)
	// CompleteReceiving Review UI action -- mark a receiving record applied once a human has reviewed its discrepancies and booked stock
	// (POST /procurement/receiving-records/{id}/complete)
	CompleteReceiving(c *gin.Context, id Id)
	// FlagDamagedLineItem Review UI action -- record a manual physical-inspection finding that some received quantity arrived damaged
	// (POST /procurement/receiving-records/{id}/line-items/{lineItemId}/damaged)
	FlagDamagedLineItem(c *gin.Context, id Id, lineItemId LineItemId)
}

